import { AfterViewInit, Component, QueryList, ViewChildren } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ENV } from '@app/env';
import { Storage } from '@ionic/storage';
import { TranslateService } from '@ngx-translate/core';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { DEFAULT_LOCALE, LOCAL_LOCALE_KEY } from '@rsApp/modules/utils/constants/constants';
import { AppSettings } from '@rsApp/modules/utils/providers/app-setting';
import { Utils } from '@rsApp/modules/utils/providers/utils';
import Swiper from 'swiper';
import { ZoomableDirective } from '../../providers/zoomable.directive';

@Component({
  selector: 'page-tutorial',
  templateUrl: 'tutorial.html',
  styleUrls: ['./tutorial.scss'],
})
export class TutorialPageComponent implements AfterViewInit {
  @ViewChildren(ZoomableDirective)
  appHammerZoomable!: QueryList<ZoomableDirective>;

  swiperRef: any;
  swiper: Swiper;
  back: string;
  info = {
    version: ENV.AppVersion,
    buildNumber: ENV.BuildNumber,
  };
  isStartTour = false;
  isDidTutorial: boolean;
  currentSlide = 0;
  firstTour: any;
  swiperSlides: any[] = [];
  tutorialList: any[] = [];
  tutorialNumber: string;
  isViewerOpen = false;
  currentImage = '';
  initialSlideIndex: number = 0;

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    public storage: Storage,
    public utils: Utils,
    public appSettings: AppSettings,
    public translate: TranslateService,
    public cre: Credential
  ) {}

  async ionViewWillEnter() {
    const currentLocale = this.translate.currentLang || (await this.storage.get(LOCAL_LOCALE_KEY)) || DEFAULT_LOCALE;
    this.appSettings.getSettingValue('tutorial_configurations').subscribe(async (rs) => {
      try {
        const parseData = typeof rs === 'string' ? JSON.parse(rs) : [];
        const items = Array.isArray(parseData.tutorial_information) ? parseData.tutorial_information : [];

        this.tutorialNumber = parseData.tutorial_version;
        this.tutorialList = items
          .map((item) => ({
            ...item,
            title: item.title?.[currentLocale] || '',
            description: item.description?.[currentLocale] || '',
          }))
          .filter(({ title, imageUrl, description }) => title?.trim() || imageUrl?.trim() || description?.trim());
        if (this.tutorialList?.length) {
          this.firstTour = this.tutorialList[0];
          this.swiperSlides = this.tutorialList.slice(1);
        }

        const tutorialCached = await this.storage.get('tutorial_version');
        const updateVersion = !tutorialCached || parseInt(tutorialCached) < parseInt(this.tutorialNumber);
        if (updateVersion) this.storage.set('tutorial_version', this.tutorialNumber);
      } catch (e) {
        this.router.navigate(['/tabs/home']);
        this.tutorialList = [];
        console.error(e);
      }
    });
  }

  startTour() {
    this.isStartTour = true;
  }

  ngAfterViewInit() {
    this.swiperRef = document.querySelector('swiper-container');
  }

  slideChanged(e) {
    this.currentSlide = e?.detail[0]?.activeIndex;
  }

  moveSlide(index: number) {
    this.swiperRef.swiper.slideTo(index);
    this.currentSlide = index;
  }

  openViewer(index: number) {
    this.currentImage = this.tutorialList[index]?.imageUrl;
    this.initialSlideIndex = index;
    this.isViewerOpen = true;
  }

  closeViewer() {
    this.currentImage = null;
    this.isViewerOpen = false;
  }

  closeTutorial() {
    if (this.cre?.currentUser?.UserId) {
      this.router.navigate(['/tabs/home']);
    } else {
      this.router.navigate(['/sign-in']);
    }
  }

  onSlideChange() {
    this.appHammerZoomable.forEach((z) => z.reset());
  }

  public getPageName() {
    return 'TutorialPage';
  }
}
